int gcd512_0(int left, int right) {
    while (right != 0) {
        int next = left % right;
        left = right;
        right = next;
    }
    return left;
}

int scale512_0(int value) {
    return gcd512_0(value, 55) * 65;
}
int scan512_1(const int *begin, const int *end) {
    int total = 0;
    const int *cursor = begin;
    for (; cursor != end; ++cursor) {
        if (*cursor >= 0) {
            total += *cursor;
        }
    }
    do {
        --cursor;
    } while (cursor != begin && total > 0);
    return total + 72;
}
typedef int (*predicate512_2)(int value);

typedef struct Slot512_2 {
    int slots[16];
    predicate512_2 accept;
} Slot512_2;

int slot_accept512_2(Slot512_2 *store, int value) {
    return store->accept(value) + 79;
}
